package com.projetok.multiplayer;

import com.projetok.prototype.*;
import com.projetok.prototype.rpg.RpgPlayerSprites;
import com.projetok.prototype.rpg.CosmeticCatalog;
import com.projetok.prototype.rpg.CosmeticRenderer;
import java.awt.*;
import java.awt.event.*;
import java.net.*;
import java.nio.file.*;
import java.util.*;
import javax.swing.*;

/** Cliente RPG experimental: envia intenções e apresenta snapshots, sem simulação autoritativa local. */
public final class RpgNetworkClientLauncher {
    private RpgNetworkClientLauncher() { }
    record Options(boolean lan,boolean cosmetics,String[] connection,CosmeticCatalog.Selection selection) { }
    static Options options(String[] args){boolean lan=false,cosmetics=false;String hair="none",clothing="none";var positional=new ArrayList<String>();for(int i=0;i<args.length;i++)switch(args[i]){case "--lan"->lan=true;case "--cosmetics"->cosmetics=true;case "--hair"->{if(++i>=args.length)throw new IllegalArgumentException("Cabelo ausente");hair=args[i];}case "--clothing"->{if(++i>=args.length)throw new IllegalArgumentException("Roupa ausente");clothing=args[i];}default->positional.add(args[i]);}if(positional.size()<3||positional.size()>4)throw new IllegalArgumentException("Uso: host porta nome [captura.png] [--lan] [--cosmetics --hair ID --clothing ID]");var selection=new CosmeticCatalog.Selection(hair,clothing);if(!cosmetics&&!selection.equals(CosmeticCatalog.Selection.none()))throw new IllegalArgumentException("Aparência exige capacidade cosmética");return new Options(lan,cosmetics,positional.toArray(String[]::new),selection);}
    public static void main(String[] args){var options=options(args);boolean allowLan=options.lan(),cosmetics=options.cosmetics();String[] connection=options.connection();String app=System.getProperty("jpackage.app-path");Path root=app==null?Path.of("."):Path.of(app).toAbsolutePath().getParent();
        SwingUtilities.invokeLater(()->{var loading=new JFrame("Spirit Gate | Conectando");loading.add(new JLabel("Carregando recursos temporarios e conectando...",SwingConstants.CENTER));loading.setSize(480,120);loading.setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);loading.setLocationRelativeTo(null);loading.setVisible(true);new SwingWorker<Object[],Void>(){protected Object[] doInBackground()throws Exception{var sprites=RpgPlayerSprites.loadOptional(root.resolve("assets/dev/player-base"),250,.5);var catalog=cosmetics?CosmeticCatalog.load(root.resolve("assets/dev/generated/corujao-iv-v1")):null;if(catalog!=null)catalog.validate(options.selection());var client=cosmetics?LocalClient.cosmetics(InetAddress.getByName(connection[0]),Integer.parseInt(connection[1]),connection[2],allowLan):allowLan?LocalClient.lan(InetAddress.getByName(connection[0]),Integer.parseInt(connection[1]),connection[2]):new LocalClient(InetAddress.getByName(connection[0]),Integer.parseInt(connection[1]),connection[2]);return new Object[]{client,sprites,catalog};}protected void done(){try{var values=get();var client=(LocalClient)values[0];var frame=open(client,(RpgPlayerSprites)values[1],connection[0]+":"+connection[1],(CosmeticCatalog)values[2],options.selection());if(connection.length==4){var shot=new javax.swing.Timer(3000,e->{try{var image=new java.awt.image.BufferedImage(frame.getWidth(),frame.getHeight(),2);var g=image.createGraphics();frame.printAll(g);g.dispose();javax.imageio.ImageIO.write(image,"png",Path.of(connection[3]).toFile());var self=client.appearances().get(client.id());java.nio.file.Files.writeString(Path.of(connection[3]+".json"),"{\"session\":"+client.id()+",\"players\":"+(client.snapshot()==null?0:client.snapshot().actors().size())+",\"appearances\":"+client.appearances().size()+",\"hair\":\""+(self==null?"none":self.hair())+"\",\"race\":\""+(self==null?"unknown":self.race())+"\",\"physicalUiApproved\":false}");}catch(Exception error){error.printStackTrace();}finally{frame.dispose();}});shot.setRepeats(false);shot.start();}}catch(Exception e){JOptionPane.showMessageDialog(null,"Conexão recusada: "+e.getMessage());}finally{loading.dispose();}}}.execute();});
    }
    /** Janela reutilizável pelo probe de dois clientes; fechamento libera sockets e timers. */
    public static JFrame open(LocalClient client,RpgPlayerSprites sprites,String endpoint){
        return open(client,sprites,endpoint,null);
    }
    public static JFrame open(LocalClient client,RpgPlayerSprites sprites,String endpoint,CosmeticCatalog catalog){
        return open(client,sprites,endpoint,catalog,CosmeticCatalog.Selection.none());
    }
    public static JFrame open(LocalClient client,RpgPlayerSprites sprites,String endpoint,CosmeticCatalog catalog,CosmeticCatalog.Selection initial){
        var template=DebugWorld.demo().snapshot();Protocol.State[] display={new Protocol.State(0,java.util.List.of())};var animation=new RemoteSpriteAnimation();
        var panel=new DebugPanel(()->NetworkClientLauncher.adapt(display[0],client.id(),template,"RPG local - movimento validado no servidor",1000));
        panel.setCustomFooter("WASD: movimento autoritativo | duas sessoes sinteticas", "Combate compartilhado e habilidades de rede ainda indisponiveis.");
        if(sprites!=null)panel.setActorRenderer((g,actor)->{if(!actor.alive())return false;var pose=animation.pose(actor.id(),System.nanoTime()/1_000_000);var appearance=client.appearances().get(actor.id());var selection=appearance==null?CosmeticCatalog.Selection.none():new CosmeticCatalog.Selection(appearance.hair(),appearance.clothing());boolean drawn=CosmeticRenderer.draw(g,sprites,catalog,selection,pose.direction(),pose.frame(),pose.walking(),actor.x(),actor.y());if(drawn){g.setColor(Color.WHITE);g.drawString(actor.name(),actor.x()-20,actor.y()-65);}return drawn;});
        JFrame frame=new JFrame("Spirit Gate | RPG LOCAL EXPERIMENTAL | "+client.id());frame.add(panel);frame.setSize(1200,800);frame.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);frame.getRootPane().putClientProperty("networkClient",client);frame.getRootPane().putClientProperty("networkPanel",panel);
        JButton reconnect=new JButton("Reconectar nova sessão");reconnect.setEnabled(false);frame.add(reconnect,BorderLayout.NORTH);boolean[] reconnecting={false};
        if(catalog!=null&&client.supportsCosmetics()){catalog.validate(initial);JPanel controls=new JPanel();controls.add(reconnect);var hair=new JComboBox<String>();var clothing=new JComboBox<String>();hair.addItem("none");clothing.addItem("none");catalog.all("hair").forEach(d->hair.addItem(d.id()));catalog.all("clothing").forEach(d->clothing.addItem(d.id()));hair.setSelectedItem(initial.hair());clothing.setSelectedItem(initial.clothing());client.appearance(initial.hair(),initial.clothing());controls.add(new JLabel("TEMPORÁRIO — cabelo/roupa"));controls.add(hair);controls.add(clothing);java.awt.event.ActionListener update=e->client.appearance((String)hair.getSelectedItem(),(String)clothing.getSelectedItem());hair.addActionListener(update);clothing.addActionListener(update);frame.add(controls,BorderLayout.NORTH);}
        reconnect.addActionListener(e->{reconnecting[0]=true;reconnect.setEnabled(false);new SwingWorker<LocalClient,Void>(){protected LocalClient doInBackground()throws Exception{return client.reconnect();}protected void done(){try{var next=get();if(!frame.isDisplayable()){next.close();return;}open(next,sprites,endpoint,catalog);frame.dispose();}catch(Exception error){JOptionPane.showMessageDialog(frame,"Reconexão recusada: "+error.getMessage());}finally{reconnecting[0]=false;}}}.execute();});
        Set<String> held=new HashSet<>();for(String key:new String[]{"W","A","S","D"})for(boolean down:new boolean[]{true,false}){String action=key+down;panel.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW).put(KeyStroke.getKeyStroke((down?"pressed ":"released ")+key),action);panel.getActionMap().put(action,new AbstractAction(){public void actionPerformed(ActionEvent e){if(down)held.add(key);else held.remove(key);}});}
        RemotePresentation[] frames={null};long[] received={0};int[] count={0};var timer=new javax.swing.Timer(33,e->{reconnect.setEnabled(!client.connected()&&!reconnecting[0]);var latest=client.connected()?client.snapshot():new Protocol.State(display[0].tick(),java.util.List.of());long now=System.nanoTime();if(latest!=null){animation.update(latest,now/1_000_000);if(frames[0]==null||!client.connected()){frames[0]=new RemotePresentation(latest,latest);received[0]=now;}else if(latest.tick()>frames[0].current().tick()){frames[0]=new RemotePresentation(frames[0].current(),latest);received[0]=now;}display[0]=frames[0].sample(Math.min(1,(now-received[0])/100_000_000d),client.id());}if(++count[0]%3==0)client.send(Protocol.Action.MOVE,(held.contains("D")?1:0)-(held.contains("A")?1:0),(held.contains("S")?1:0)-(held.contains("W")?1:0));panel.setCustomHud(java.util.List.of("RPG LOCAL EXPERIMENTAL",endpoint,"Sessão "+client.id(),"Tick servidor: "+display[0].tick(),client.connected()?"Conectado":"Desconectado: "+client.problem(),"Jogadores: "+display[0].actors().size(),"WASD: movimento","Combate de rede indisponível","Raça atribuída pelo servidor","Sem contas ou saves pessoais"));panel.repaint();});
        frame.addWindowFocusListener(new WindowAdapter(){public void windowLostFocus(WindowEvent e){held.clear();client.send(Protocol.Action.MOVE,0,0);}});frame.addWindowListener(new WindowAdapter(){public void windowClosed(WindowEvent e){timer.stop();client.close();}});timer.start();frame.setVisible(true);return frame;
    }
}
